local VERSION='9.0.0'
local kits, forecasts, resupply = {}, {}, {}
local function uid(p)return('%s-%s-%04d'):format(p,os.time(),math.random(0,9999))end
exports('BuildAdaptiveCriticalCareKitV9',function(profile,stock)local required={trauma={tourniquet=4,gauze=8,chest_seal=4,iv_kit=4,blood=2},cardiac={aed_pads=2,epinephrine=6,amiodarone=2,airway_kit=2},respiratory={oxygen=2,airway_kit=3,nebulizer=2}};local template=required[tostring(profile)]or required.trauma;local shortages={};for item,count in pairs(template)do if(tonumber(stock and stock[item])or 0)<count then shortages[item]=count-(tonumber(stock and stock[item])or 0)end end;local kit={id=uid('KIT9'),profile=profile,required=template,shortages=shortages,status=next(shortages)and'incomplete'or'ready',createdAt=os.time()};kits[kit.id]=kit;return kit.status=='ready',kit end)
exports('ForecastSupplyBurnV9',function(history,horizonHours)local rates={};for _,row in ipairs(type(history)=='table'and history or{})do local item=tostring(row.item);rates[item]=(rates[item]or 0)+(tonumber(row.used)or 0)end;local result={id=uid('BURN'),horizonHours=tonumber(horizonHours)or 24,forecast={},createdAt=os.time()};for item,total in pairs(rates)do result.forecast[item]=math.ceil(total*(result.horizonHours/24))end;forecasts[result.id]=result;return result end)
exports('CreateEmergencyResupplyV9',function(destination,items,priority)local item={id=uid('RESUP'),destination=destination,items=items or{},priority=priority or 1,status='requested',createdAt=os.time()};resupply[item.id]=item;return item.id,item end)
exports('GetV9InventoryBoard',function()return{version=VERSION,kits=kits,forecasts=forecasts,resupply=resupply,generatedAt=os.time()}end)
CreateThread(function()Wait(6600);print('[dpn-medical-inventory] v9 adaptive critical kits and supply resilience active')end)
